    44→    /**
    45→     * @returns {'off'|'all'|'paid'}
    46→     */
    47→    get enabled() {
    48→        const setting = this.settingsCache.get('comments_enabled');
    49→        if (setting === 'off' || setting === 'all' || setting === 'paid') {
    50→            return setting;
    51→        }
