    55→    /** @private */
    56→    checkEnabled() {
    57→        if (this.enabled === 'off') {
    58→            throw new errors.MethodNotAllowedError({
    59→                message: tpl(messages.commentsNotEnabled)
    60→            });
    61→        }
    62→    }
    63→
    64→    /** @private */
    65→    checkCommentAccess(memberModel) {
    66→        if (this.enabled === 'paid' && memberModel.get('status') === 'free') {
    67→            throw new errors.NoPermissionError({
    68→                message: tpl(messages.cannotCommentOnPost)
    69→            });
    70→        }
    71→    }
    72→
    73→    /** @private */
    74→    checkPostAccess(postModel, memberModel) {
    75→        const access = this.contentGating.checkPostAccess(postModel.toJSON(), memberModel.toJSON());
    76→        if (access === this.contentGating.BLOCK_ACCESS) {
    77→            throw new errors.NoPermissionError({
    78→                message: tpl(messages.cannotCommentOnPost)
    79→            });
    80→        }
    81→    }
