    83→    /** @private */
    84→    async sendNewCommentNotifications(comment) {
    85→        await this.emails.notifyPostAuthors(comment);
    86→
    87→        if (comment.get('parent_id')) {
    88→            await this.emails.notifyParentCommentAuthor(comment, {type: 'parent'});
    89→        }
    90→        if (comment.get('in_reply_to_id')) {
    91→            await this.emails.notifyParentCommentAuthor(comment, {type: 'in_reply_to'});
    92→        }
    93→    }
