    95→    async likeComment(commentId, member, options = {}) {
    96→        this.checkEnabled();
    97→
    98→        const memberModel = await this.models.Member.findOne({
    99→            id: member.id
   100→        }, {
   101→            require: true,
   102→            ...options,
   103→            withRelated: ['products']
   104→        });
   105→
   106→        this.checkCommentAccess(memberModel);
   107→
   108→        const data = {
   109→            member_id: memberModel.id,
   110→            comment_id: commentId
   111→        };
