   124→    async unlikeComment(commentId, member, options = {}) {
   125→        this.checkEnabled();
   126→
   127→        try {
   128→            await this.models.CommentLike.destroy({
   129→                ...options,
   130→                destroyBy: {
   131→                    member_id: member.id,
   132→                    comment_id: commentId
   133→                },
   134→                require: true
   135→            });
