   147→    async reportComment(commentId, reporter) {
   148→        this.checkEnabled();
   149→        const comment = await this.models.Comment.findOne({id: commentId}, {require: true});
   150→
   151→        // Check if this reporter already reported this comment (then don't send an email)?
   152→        const existing = await this.models.CommentReport.findOne({
   153→            comment_id: comment.id,
   154→            member_id: reporter.id
   155→        });
   156→
   157→        if (existing) {
   158→            // Ignore silently for now
   159→            return;
   160→        }
   161→
   162→        // Save report model
   163→        await this.models.CommentReport.add({
   164→            comment_id: comment.id,
   165→            member_id: reporter.id
   166→        });
   167→
   168→        await this.emails.notifyReport(comment, reporter);
