   181→    /**
   182→     * @typedef {Object} AdminBrowseAllOptions
   183→     * @property {boolean} includeNested - If true, include replies in flat list; if false, only top-level comments
   184→     * @property {string[]} [withRelated] - Relations to include (e.g. ['member', 'post'])
   185→     * @property {string} [filter] - NQL filter string
   186→     * @property {Function} [mongoTransformer] - Function to transform parsed NQL filter
   187→     * @property {{op: string, value: number}} [reportCount] - Filter by report count (op: '=', '>', '>=', '<', '<=', '!=')
   188→     * @property {string} order - Order string (e.g. 'created_at desc')
   189→     * @property {number} [page] - Page number
   190→     * @property {number} [limit] - Results per page
   191→     */
   192→
   193→    /**
   194→     * Browse all comments across the site for admin moderation.
   195→     * Does not check if comments are enabled - admins can moderate existing comments.
   196→     *
   197→     * Service responsibility: Business logic and data access.
   198→     * Receives clean, typed parameters - no frame/HTTP knowledge.
   199→     *
   200→     * @param {AdminBrowseAllOptions} options
   201→     */
   202→    async getAdminAllComments({includeNested, filter, mongoTransformer, reportCount, order, page, limit}) {
   203→        return await this.models.Comment.findPage({
   204→            withRelated: ['member', 'post', 'count.replies', 'count.likes', 'count.reports', 'inReplyTo', 'parent'],
   205→            filter,
   206→            mongoTransformer,
   207→            reportCount,
   208→            order,
   209→            page,
   210→            limit,
   211→            parentId: includeNested ? undefined : null,
   212→            isAdmin: true,
   213→            browseAll: true
   214→        });
   215→    }
   216→
   217→    async getAdminComments(options) {
   218→        this.checkEnabled();
   219→        const page = await this.models.Comment.findPage({...options, parentId: null, isAdmin: true});
   220→
   221→        return page;
   222→    }
   223→
   224→    /**
   225→     * @param {string} id - The ID of the Comment to get replies from
   226→     * @param {any} options
   227→     */
   228→    async getReplies(id, options) {
   229→        this.checkEnabled();
   230→        const page = await this.models.Comment.findPage({...options, parentId: id});
   231→
   232→        return page;
   233→    }
