   235→    /**
   236→     * Get reporters for a comment (admin only)
   237→     * @param {string} commentId - The ID of the Comment to get reporters for
   238→     * @param {any} options - Query options (page, limit)
   239→     */
   240→    async getCommentReporters(commentId, options = {}) {
   241→        const comment = await this.models.Comment.findOne({id: commentId});
   242→        if (!comment) {
   243→            throw new errors.NotFoundError({
   244→                message: tpl(messages.commentNotFound)
   245→            });
   246→        }
   247→
   248→        const {page, limit} = options;
   249→        const result = await this.models.CommentReport.findPage({
   250→            filter: `comment_id:'${commentId}'`,
   251→            withRelated: ['member'],
   252→            order: 'created_at desc',
   253→            page,
   254→            limit
   255→        });
   256→
   257→        return result;
   258→    }
   259→
   260→    /**
   261→     * Get likes for a comment (admin only)
   262→     * @param {string} commentId - The ID of the Comment to get likes for
   263→     * @param {any} options - Query options (page, limit)
   264→     */
   265→    async getCommentLikes(commentId, options = {}) {
   266→        const comment = await this.models.Comment.findOne({id: commentId});
   267→        if (!comment) {
   268→            throw new errors.NotFoundError({
   269→                message: tpl(messages.commentNotFound)
   270→            });
   271→        }
   272→
   273→        const {page, limit} = options;
   274→        const result = await this.models.CommentLike.findPage({
   275→            filter: `comment_id:'${commentId}'`,
   276→            withRelated: ['member'],
   277→            order: 'created_at desc',
   278→            page,
   279→            limit
   280→        });
   281→
   282→        return result;
   283→    }
