   285→    /**
   286→     * @param {string} id - The ID of the Comment to get
   287→     * @param {any} options
   288→     */
   289→    async getCommentByID(id, options) {
   290→        this.checkEnabled();
   291→        const model = await this.models.Comment.findOne({id}, options);
   292→
   293→        if (!model) {
   294→            throw new errors.NotFoundError({
   295→                message: tpl(messages.commentNotFound)
   296→            });
   297→        }
   298→
   299→        return model;
   300→    }
