   302→    /**
   303→     * @param {string} post - The ID of the Post to comment on
   304→     * @param {string} member - The ID of the Member to comment as
   305→     * @param {string} comment - The HTML content of the Comment
   306→     * @param {any} options
   307→     * @param {Date} [createdAt] - Optional custom created_at timestamp
   308→     */
   309→    async commentOnPost(post, member, comment, options, createdAt) {
   310→        this.checkEnabled();
   311→        const memberModel = await this.models.Member.findOne({
   312→            id: member
   313→        }, {
   314→            require: true,
   315→            ...options,
   316→            withRelated: ['products']
   317→        });
   318→
   319→        this.checkCommentAccess(memberModel);
   320→
   321→        const postModel = await this.models.Post.findOne({
   322→            id: post
   323→        }, {
   324→            require: true,
   325→            ...options,
   326→            withRelated: ['tiers']
   327→        });
   328→
   329→        this.checkPostAccess(postModel, memberModel);
   330→
   331→        const commentData = {
   332→            post_id: post,
   333→            member_id: member,
   334→            parent_id: null,
   335→            html: comment,
   336→            status: 'published'
   337→        };
   338→
   339→        if (createdAt) {
   340→            commentData.created_at = createdAt;
   341→        }
   342→
   343→        const model = await this.models.Comment.add(commentData, options);
   344→
   345→        if (!options.context.internal) {
   346→            await this.sendNewCommentNotifications(model);
   347→        }
   348→
   349→        DomainEvents.dispatch(MemberCommentEvent.create({
   350→            memberId: member,
   351→            postId: post,
   352→            commentId: model.id
   353→        }));
   354→
   355→        // Instead of returning the model, fetch it again, so we have all the relations properly fetched
   356→        return await this.models.Comment.findOne({id: model.id}, {...options, require: true});
   357→    }
   358→
   359→    /**
   360→     * @param {string} parent - The ID of the Comment to reply to
   361→     * @param {string} inReplyTo - The ID of the Reply to reply to
   362→     * @param {string} member - The ID of the Member to comment as
   363→     * @param {string} comment - The HTML content of the Comment
   364→     * @param {any} options
   365→     * @param {Date} [createdAt] - Optional custom created_at timestamp
   366→     */
   367→    async replyToComment(parent, inReplyTo, member, comment, options, createdAt) {
   368→        this.checkEnabled();
   369→        const memberModel = await this.models.Member.findOne({
   370→            id: member
   371→        }, {
   372→            require: true,
   373→            ...options,
   374→            withRelated: ['products']
   375→        });
   376→
   377→        this.checkCommentAccess(memberModel);
   378→
   379→        const parentComment = await this.getCommentByID(parent, options);
   380→        if (!parentComment) {
   381→            throw new errors.BadRequestError({
   382→                message: tpl(messages.commentNotFound)
   383→            });
   384→        }
   385→
   386→        if (parentComment.get('parent_id') !== null) {
   387→            throw new errors.BadRequestError({
   388→                message: tpl(messages.replyToReply)
   389→            });
   390→        }
   391→
   392→        const postModel = await this.models.Post.findOne({
   393→            id: parentComment.get('post_id')
   394→        }, {
   395→            require: true,
   396→            ...options,
   397→            withRelated: ['tiers']
   398→        });
   399→
   400→        this.checkPostAccess(postModel, memberModel);
   401→
   402→        let inReplyToComment;
   403→        if (parent && inReplyTo) {
   404→            inReplyToComment = await this.getCommentByID(inReplyTo, options);
   405→
   406→            // we only allow references to published comments to avoid leaking
   407→            // hidden data via the snippet included in API responses
   408→            if (inReplyToComment && inReplyToComment.get('status') !== 'published') {
   409→                inReplyToComment = null;
   410→            }
   411→
   412→            // we don't allow in_reply_to references across different parents
   413→            if (inReplyToComment && inReplyToComment.get('parent_id') !== parent) {
   414→                inReplyToComment = null;
   415→            }
   416→        }
   417→
   418→        const commentData = {
   419→            post_id: parentComment.get('post_id'),
   420→            member_id: member,
   421→            parent_id: parentComment.id,
   422→            in_reply_to_id: inReplyToComment && inReplyToComment.get('id'),
   423→            html: comment,
   424→            status: 'published'
   425→        };
   426→
   427→        if (createdAt) {
   428→            commentData.created_at = createdAt;
   429→        }
   430→
   431→        const model = await this.models.Comment.add(commentData, options);
   432→
   433→        if (!options.context.internal) {
   434→            await this.sendNewCommentNotifications(model);
   435→        }
   436→
   437→        DomainEvents.dispatch(MemberCommentEvent.create({
   438→            memberId: member,
   439→            postId: parentComment.get('post_id'),
   440→            commentId: model.id
   441→        }));
   442→
   443→        // Instead of returning the model, fetch it again, so we have all the relations properly fetched
   444→        return await this.models.Comment.findOne({id: model.id}, {...options, require: true});
   445→    }
   446→
   447→    /**
   448→     * @param {string} id - The ID of the Comment to delete
   449→     * @param {string} member - The ID of the Member to delete as
   450→     * @param {any} options
   451→     */
   452→    async deleteComment(id, member, options) {
   453→        this.checkEnabled();
   454→        const existingComment = await this.getCommentByID(id, options);
   455→
   456→        if (existingComment.get('member_id') !== member) {
   457→            throw new errors.NoPermissionError({
   458→                // todo fix message
   459→                message: tpl(messages.memberNotFound)
   460→            });
   461→        }
   462→
   463→        const model = await this.models.Comment.edit({
   464→            status: 'deleted'
   465→        }, {
   466→            id,
   467→            require: true,
   468→            ...options
   469→        });
   470→
   471→        return model;
   472→    }
   473→
   474→    /**
   475→     * @param {string} id - The ID of the Comment to edit
   476→     * @param {string} member - The ID of the Member to edit as
   477→     * @param {string} comment - The new HTML content of the Comment
   478→     * @param {any} options
   479→     */
   480→    async editCommentContent(id, member, comment, options) {
   481→        this.checkEnabled();
   482→        const existingComment = await this.getCommentByID(id, options);
   483→
   484→        if (!comment) {
   485→            return existingComment;
   486→        }
   487→
   488→        if (existingComment.get('member_id') !== member) {
   489→            throw new errors.NoPermissionError({
   490→                message: tpl(messages.cannotEditComment)
   491→            });
   492→        }
   493→
   494→        const model = await this.models.Comment.edit({
   495→            html: comment,
   496→            edited_at: new Date()
   497→        }, {
   498→            id,
   499→            require: true,
   500→            ...options
   501→        });
   502→
   503→        return model;
   504→    }
   505→
   506→    /**
   507→     * Bulk update comment status based on NQL filter
   508→     * @param {string} filter - NQL filter string (e.g., "member_id:'abc123'+status:published")
   509→     * @param {string} status - New status ('hidden', 'published', 'deleted')
   510→     */
   511→    async bulkUpdateStatus(filter, status) {
   512→        await this.models.Comment.bulkEditWhere({
   513→            data: {status},
   514→            where: byNQL(filter)
   515→        });
   516→    }
   517→
   518→    async getMemberIdByUUID(uuid, options) {
   519→        const member = await this.models.Member.findOne({uuid}, options);
   520→
   521→        if (!member) {
   522→            throw new errors.NotFoundError({
   523→                message: tpl(messages.memberNotFound)
   524→            });
   525→        }
   526→
   527→        return member.id;
   528→    }
   529→}
   530→
   531→module.exports = CommentsService;
